#!/usr/bin/env node

// Deterministic evidence of the user-approved SA-1 through SA-9 amendments.
// The approval oracle is a manually reviewed normalization of the nine diff
// blocks in the approved action plan. It is intentionally never generated by
// this tool: current master text therefore cannot bless its own amendment.

import fs from "node:fs";
import path from "node:path";
import process from "node:process";
import { spawnSync } from "node:child_process";
import { implementationRoot, repoRelative, sha256 } from "./lib.mjs";

const SEALED_APPROVAL_ORACLE_SHA256 = "f629f6bd6c2cb6eea0fbd97108f9c9a2fadcd315c09a158143b7ffa4e62966df";
const SEALED_APPROVAL_SOURCE_SHA256 = "9298abb545e85563c4cd971d2a2fc4b129b8b767bce2c82c9677aff4166f138d";

const baseline = path.join(
  implementationRoot,
  "_archive/pre-unification-baseline/ioi-target-end-state-master-implementation-guide.md",
);
const current = path.join(implementationRoot, "ioi-target-end-state-master-implementation-guide.md");
const output = path.join(
  implementationRoot,
  "audits/reconciliation/approved-sequencer-amendments/sa-1-through-sa-9.applied.patch",
);
const approvalOracle = path.join(
  implementationRoot,
  "audits/reconciliation/approved-sequencer-amendments/sa-1-through-sa-9.approval-oracle.patch",
);
const approvalMetadata = path.join(
  implementationRoot,
  "audits/reconciliation/approved-sequencer-amendments/sa-1-through-sa-9.approval-oracle.v1.json",
);

function fail(message) {
  process.stderr.write(`approved sequencer diff failed: ${message}\n`);
  process.exit(1);
}

function buildPatch() {
  const result = spawnSync("diff", [
    "-u",
    "--label", "a/internal-docs/implementation/ioi-target-end-state-master-implementation-guide.md",
    "--label", "b/internal-docs/implementation/ioi-target-end-state-master-implementation-guide.md",
    baseline,
    current,
  ], { encoding: "utf8" });
  if (result.status !== 1 || !result.stdout.startsWith("--- a/")) {
    fail(result.status === 0 ? "baseline and current master unexpectedly have no approved diff" : (result.stderr || `diff exited ${result.status}`).trim());
  }
  return result.stdout;
}

const mode = process.argv[2];
if (process.argv.length !== 3 || !["--write", "--check"].includes(mode)) {
  fail("usage: generate-approved-sequencer-diff.mjs --write|--check");
}
const expected = buildPatch();
if (!fs.existsSync(approvalMetadata)) fail(`${repoRelative(approvalMetadata)} is missing`);
const metadata = JSON.parse(fs.readFileSync(approvalMetadata, "utf8"));
const actionPlan = path.join(
  implementationRoot,
  "_archive/pre-link-repair/2026-07-23/audits/2026-07-22-directory-unification-plan.md.pre-link-repair",
);
if (metadata.schema_version !== "ioi.program.sequencer-amendment-approval-oracle.v1"
  || metadata.document_class !== "work_record"
  || JSON.stringify(metadata.approved_amendments) !== JSON.stringify(Array.from({ length: 9 }, (_, index) => `SA-${index + 1}`))
  || metadata.approval_oracle?.generated_by_current_master !== false) {
  fail("approval-oracle metadata has an invalid schema, class, amendment set, or provenance boundary");
}
for (const [label, absolute, declared] of [
  ["approved action plan", actionPlan, metadata.approval_source_sha256],
  ["sealed baseline master", baseline, metadata.baseline_master?.sha256],
  ["approval oracle", approvalOracle, metadata.approval_oracle?.sha256],
  ["current master", current, metadata.expected_current_master_sha256],
]) {
  if (!fs.existsSync(absolute) || sha256(fs.readFileSync(absolute)) !== declared) fail(`${label} differs from sealed metadata`);
}
if (!fs.existsSync(approvalOracle)) {
  fail(`${repoRelative(approvalOracle)} is missing; this tool cannot generate its approval oracle`);
}
const approved = fs.readFileSync(approvalOracle, "utf8");
if (sha256(approved) !== SEALED_APPROVAL_ORACLE_SHA256) fail(`approval oracle differs from checker-sealed SHA-256 ${SEALED_APPROVAL_ORACLE_SHA256}`);
if (sha256(fs.readFileSync(actionPlan)) !== SEALED_APPROVAL_SOURCE_SHA256) fail(`approved action-plan source differs from checker-sealed SHA-256 ${SEALED_APPROVAL_SOURCE_SHA256}`);
if (expected !== approved) {
  fail(`master amendment differs from the sealed SA-1 through SA-9 approval oracle (approved ${sha256(approved)}, current ${sha256(expected)})`);
}
if (mode === "--write") {
  fs.mkdirSync(path.dirname(output), { recursive: true });
  fs.writeFileSync(output, approved);
  process.stdout.write(`applied sequencer diff written after approval-oracle match: ${repoRelative(output)}, sha256 ${sha256(approved)}\n`);
} else {
  if (!fs.existsSync(output)) fail(`${repoRelative(output)} is missing`);
  const actual = fs.readFileSync(output, "utf8");
  if (actual !== approved) fail(`${repoRelative(output)} is stale (approved ${sha256(approved)}, found ${sha256(actual)})`);
  process.stdout.write(`approved sequencer diff check passed: baseline, current master, sealed oracle, and applied artifact all match sha256 ${sha256(actual)}\n`);
}
